using System; using System.Data; using System.Data.SqlClient; using System.Linq; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp { public partial class LoginPage : BasePage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object Authenticate(string username, string password, bool rememberMe) { SecurityHelper.ValidateCsrfOrThrow(); var normalized = (username ?? string.Empty).Trim(); if (string.IsNullOrWhiteSpace(normalized) || string.IsNullOrWhiteSpace(password)) return new { success = false, message = "Invalid username or password." }; var ip = SecurityHelper.GetIpAddress(); var failedAttempts = Convert.ToInt32(DbHelper.ExecuteScalar(@"SELECT COUNT(1) FROM LoginAttempts WHERE (Username = @Username OR IPAddress = @IPAddress) AND IsSuccessful = 0 AND AttemptTime >= DATEADD(MINUTE, -15, GETUTCDATE())", CommandType.Text, new SqlParameter("@Username", normalized), new SqlParameter("@IPAddress", ip))); if (failedAttempts >= 5) return new { success = false, message = "Invalid username or password." }; var table = DbHelper.ExecuteDataTable(@"SELECT TOP 1 UserID, Username, PasswordHash, IsActive, IsLocked, MustChangePassword FROM Users WHERE (Username = @Username OR Email = @Username) AND IsDeleted = 0", CommandType.Text, new SqlParameter("@Username", normalized)); if (table.Rows.Count == 0) { RecordLoginAttempt(normalized, ip, false, "User lookup failed"); return new { success = false, message = "Invalid username or password." }; } var row = table.Rows[0]; if (!Convert.ToBoolean(row["IsActive"]) || Convert.ToBoolean(row["IsLocked"]) || !PasswordHasher.VerifyPassword(password, row["PasswordHash"].ToString())) { RecordLoginAttempt(normalized, ip, false, "Invalid credentials or locked account"); return new { success = false, message = "Invalid username or password." }; } var userId = Convert.ToInt32(row["UserID"]); var rolesTable = DbHelper.ExecuteDataTable(@"SELECT r.RoleName FROM Roles r INNER JOIN UserRoles ur ON ur.RoleID = r.RoleID WHERE ur.UserID = @UserID AND ur.IsActive = 1", CommandType.Text, new SqlParameter("@UserID", userId)); var roleList = string.Join(",", rolesTable.Rows.Cast<DataRow>().Select(r => r["RoleName"].ToString()).ToArray()); SessionManager.CreateSession(userId, row["Username"].ToString(), roleList, rememberMe); RecordLoginAttempt(normalized, ip, true, null); AuditLogger.Log(userId, "LOGIN", "Authentication", "Login.aspx", null, null, null); return new { success = true, redirectUrl = Convert.ToBoolean(row["MustChangePassword"]) ? "ResetPassword.aspx?force=1" : (roleList.Contains("Customer") ? "Account.aspx" : "Admin/Dashboard.aspx") }; } private static void RecordLoginAttempt(string username, string ipAddress, bool isSuccessful, string failureReason) { DbHelper.ExecuteNonQuery(@"INSERT INTO LoginAttempts (Username, IPAddress, AttemptTime, IsSuccessful, FailureReason) VALUES (@Username, @IPAddress, GETUTCDATE(), @IsSuccessful, @FailureReason)", CommandType.Text, new SqlParameter("@Username", username), new SqlParameter("@IPAddress", ipAddress), new SqlParameter("@IsSuccessful", isSuccessful), new SqlParameter("@FailureReason", (object)failureReason ?? DBNull.Value)); } } }
